17	package org.springframework.samples.petclinic.service;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.stereotype.Component;
21	
22	import java.time.Clock;
23	import java.time.LocalDate;
24	
25	/**
26	 * Derives an owner's numeric membership level. The level starts at 1 and gains a
27	 * point for each qualifying attribute:
28	 * <ul>
29	 *   <li>+1 when the owner has an email address on file;</li>
30	 *   <li>+1 when the owner has no namesakes ({@code namesakeCount} is 0);</li>
31	 *   <li>+1 when the owner's tenure exceeds {@value #TENURE_THRESHOLD_DAYS} days.</li>
32	 * </ul>
33	 * The result is capped at {@value #MAX_LEVEL}. Because a brand-new owner has zero
34	 * tenure, only the first two attributes can apply on creation, so a new owner never
35	 * exceeds level 3; level 4 is attainable only once tenure passes the threshold.
36	 */
37	@Component
38	public class MembershipLevelEvaluator {
39	
40	    /** The level every owner starts at before any qualifying attribute is counted. */
41	    static final int BASE_LEVEL = 1;
42	
43	    /** Highest level attainable. */
44	    static final int MAX_LEVEL = 4;
45	
46	    /** Tenure, in days, that must be exceeded for the tenure attribute to apply. */
47	    static final long TENURE_THRESHOLD_DAYS = 365;
48	
49	    private final Clock clock;
50	
51	    public MembershipLevelEvaluator() {
52	        this(Clock.systemDefaultZone());
53	    }
54	
55	    MembershipLevelEvaluator(Clock clock) {
56	        this.clock = clock;
57	    }
58	
59	    /**
60	     * @param owner the owner whose level is evaluated
61	     * @return the owner's membership level, or {@code null} when the owner is not known
62	     */
63	    public Integer levelFor(Owner owner) {
64	        if (owner == null) {
65	            return null;
66	        }
67	        int level = BASE_LEVEL;
68	        if (owner.hasEmail()) {
69	            level++;
70	        }
71	        if (hasNoNamesakes(owner)) {
72	            level++;
73	        }
74	        if (hasQualifyingTenure(owner)) {
75	            level++;
76	        }
77	        return Math.min(level, MAX_LEVEL);
78	    }
79	
80	    private boolean hasNoNamesakes(Owner owner) {
81	        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
82	    }
83	
84	    private boolean hasQualifyingTenure(Owner owner) {
85	        return owner.tenureInDays(LocalDate.now(clock)) > TENURE_THRESHOLD_DAYS;
86	    }
87	}
