16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "registration_date")
64	    private LocalDate registrationDate;
65	
66	    @Column(name = "birth_date")
67	    private LocalDate birthDate;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "possible_duplicate")
76	    private Boolean possibleDuplicate;
77	
78	    @Column(name = "possible_duplicate_of")
79	    private Integer possibleDuplicateOf;
80	
81	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
82	    private Set<Pet> pets;
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = telephone;
106	    }
107	
108	    public String getEmail() {
109	        return this.email;
110	    }
111	
112	    public void setEmail(String email) {
113	        this.email = email;
114	    }
115	
116	    /**
117	     * Whether this owner has a non-blank email address on file.
118	     */
119	    public boolean hasEmail() {
120	        return this.email != null && !this.email.isBlank();
121	    }
122	
123	    public String getPostcode() {
124	        return this.postcode;
125	    }
126	
127	    public void setPostcode(String postcode) {
128	        this.postcode = postcode;
129	    }
130	
131	    public String getCustomerCode() {
132	        return this.customerCode;
133	    }
134	
135	    public void setCustomerCode(String customerCode) {
136	        this.customerCode = customerCode;
137	    }
138	
139	    public LocalDate getRegistrationDate() {
140	        return this.registrationDate;
141	    }
142	
143	    public void setRegistrationDate(LocalDate registrationDate) {
144	        this.registrationDate = registrationDate;
145	    }
146	
147	    /**
148	     * The owner's tenure, in whole days elapsed from its registration date up to
149	     * {@code asOf}. Returns 0 when the registration date is absent (as for a brand-new
150	     * owner) or has not yet elapsed.
151	     */
152	    public long tenureInDays(LocalDate asOf) {
153	        if (this.registrationDate == null || asOf == null) {
154	            return 0;
155	        }
156	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, asOf));
157	    }
158	
159	    public LocalDate getBirthDate() {
160	        return this.birthDate;
161	    }
162	
163	    public void setBirthDate(LocalDate birthDate) {
164	        this.birthDate = birthDate;
165	    }
166	
167	    public String getHouseholdId() {
168	        return this.householdId;
169	    }
170	
171	    public void setHouseholdId(String householdId) {
172	        this.householdId = householdId;
173	    }
174	
175	    public Integer getNamesakeCount() {
176	        return this.namesakeCount;
177	    }
178	
179	    public void setNamesakeCount(Integer namesakeCount) {
180	        this.namesakeCount = namesakeCount;
181	    }
182	
183	    public Boolean getPossibleDuplicate() {
184	        return this.possibleDuplicate;
185	    }
186	
187	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
188	        this.possibleDuplicate = possibleDuplicate;
189	    }
190	
191	    public Integer getPossibleDuplicateOf() {
192	        return this.possibleDuplicateOf;
193	    }
194	
195	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
196	        this.possibleDuplicateOf = possibleDuplicateOf;
197	    }
198	
199	    protected Set<Pet> getPetsInternal() {
200	        if (this.pets == null) {
201	            this.pets = new HashSet<>();
202	        }
203	        return this.pets;
204	    }
205	
206	    protected void setPetsInternal(Set<Pet> pets) {
207	        this.pets = pets;
208	    }
209	
210	    public List<Pet> getPets() {
211	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
212	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
213	        return Collections.unmodifiableList(sortedPets);
214	    }
215	
216	    public void setPets(List<Pet> pets) {
217	        this.pets = new HashSet<>(pets);
218	    }
219	
220	    public void addPet(Pet pet) {
221	        getPetsInternal().add(pet);
222	        pet.setOwner(this);
223	    }
224	
225	    /**
226	     * Return the Pet with the given name, or null if none found for this Owner.
227	     *
228	     * @param name to test
229	     * @return true if pet name is already in use
230	     */
231	    public Pet getPet(String name) {
232	        return getPet(name, false);
233	    }
234	
235	    /**
236	     * Return the Pet with the given name, or null if none found for this Owner.
237	     *
238	     * @param name to test
239	     * @return true if pet name is already in use
240	     */
241	    public Pet getPet(String name, boolean ignoreNew) {
242	        name = name.toLowerCase();
243	        for (Pet pet : getPetsInternal()) {
244	            if (!ignoreNew || !pet.isNew()) {
245	                String compName = pet.getName();
246	                compName = compName.toLowerCase();
247	                if (compName.equals(name)) {
248	                    return pet;
249	                }
250	            }
251	        }
252	        return null;
253	    }
254	
255	    public Pet getPet(Integer petId) {
256	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
257	    }
258	
259	    @Override
260	    public String toString() {
261	        return new ToStringCreator(this)
262	
263	            .append("id", this.getId())
264	            .append("new", this.isNew())
265	            .append("lastName", this.getLastName())
266	            .append("firstName", this.getFirstName())
267	            .append("address", this.address)
268	            .append("city", this.city)
269	            .append("telephone", this.telephone)
270	            .toString();
271	    }
272	}
